/// Simple in-memory settings store backed by a JSON file on disk.
///
/// New settings live at `~/Library/Application Support/Zoomies/settings.json`.
/// On first launch after upgrading, the old `~/.screenshot_app_settings.json`
/// file is read and copied to the new location.
final class SettingsStore {
    typealias PersistWriter = (_ data: Data, _ url: URL) throws -> Void

    private(set) var settings: Settings

    /// True when the most recent `load()` reset one or more semantically invalid
    /// fields *and* those repairs were written durably. An unwritable file must
    /// not claim a repair, or the launch notice would repeat forever.
    private(set) var didRepairInvalidSettingsOnLastLoad = false

    private let fileURL: URL
    private let legacyFileURL: URL?
    private let fileManager: FileManager
    private let persistWriter: PersistWriter?

    init(fileManager: FileManager = .default,
         fileURL: URL? = nil,
         legacyFileURL: URL? = nil,
         persistWriter: PersistWriter? = nil) {
        self.fileManager = fileManager
        self.persistWriter = persistWriter

        if let fileURL {
            self.fileURL = fileURL
            self.legacyFileURL = legacyFileURL
        } else {
            let home = fileManager.homeDirectoryForCurrentUser
            self.fileURL = home
                .appendingPathComponent("Library", isDirectory: true)
                .appendingPathComponent("Application Support", isDirectory: true)
                .appendingPathComponent("Zoomies", isDirectory: true)
                .appendingPathComponent("settings.json", isDirectory: false)
            self.legacyFileURL = legacyFileURL
                ?? home.appendingPathComponent(".screenshot_app_settings.json", isDirectory: false)
        }

        self.settings = .default
    }

    /// Loads settings from disk if possible, otherwise keeps defaults.
    ///
    /// On any decoding error, the file is ignored and defaults are used.
    func load() {
        didRepairInvalidSettingsOnLastLoad = false
        do {
            if fileManager.fileExists(atPath: fileURL.path) {
                let repaired = applyLoadedSettings(try loadSettings(from: fileURL))
                persistLoadedSettings(repaired: repaired)
                return
            }

            if let legacyFileURL, fileManager.fileExists(atPath: legacyFileURL.path) {
                let repaired = applyLoadedSettings(try loadSettings(from: legacyFileURL))
                persistLoadedSettings(repaired: repaired)
                return
            }

            // First launch – write out defaults so future loads succeed.
            settings = .default
            persistLoadedSettings(repaired: false)
        } catch {
            // Fall back to defaults but do not overwrite the possibly-bad file.
            // This mirrors many macOS apps' behavior.
            settings = .default
        }
    }

    private func applyLoadedSettings(_ loaded: Settings) -> Bool {
        let normalized = loaded.normalizedReportingRepairs()
        settings = normalized.settings
        return normalized.repairedInvalidFields
    }

private func complete(action: FinalAction, note: String?) {
    guard !hasFinished, !isFinalActionInProgress else { return }

    if action == .closeOnly {
        closeWorkflowWithoutDeleting()
        return
    }

    if isWaitingForInitialFilePersistence {
        isFinalActionInProgress = true
        waitForInitialFilePersistence { [weak self] ready in
            guard let self else { return }
            self.isFinalActionInProgress = false
            guard ready else { return }
            self.complete(action: action, note: note)
        }
        return
    }

    isFinalActionInProgress = true
    guard retryInitialCapturePersistenceIfNeeded() else {
        isFinalActionInProgress = false
        return
    }

    if action == .deleteOnly {
        guard deleteConfirmer() else {
            isFinalActionInProgress = false
            return
        }
        guard deleteSourceFileAndBackup() else {
            isFinalActionInProgress = false
            return
        }
        closeInputControllers()
        clearPendingEditorState()
        finishWorkflow()
        return
    }

    let pendingImage: NSImage? = {
        if let editor = editorController {
            let image = editor.currentCompositeImage()
            pendingEditorState = editor.currentEditableState()
            editor.dismissWithoutCompletion()
            editorController = nil
            return image
        }
        return pendingEditedImage
    }()

    let imageToPersist: NSImage?
    var baselinePNG: Data?
    var embedPrompt: String?
    var embedEditorState: EditorCanvasState?
    if let pendingImage {
        var finalImage = pendingImage
        if let note,
           let preparedNote = WorkflowNoteRenderer.prepareNoteText(note, settings: settingsStore.settings) {
            guard let noted = WorkflowNoteRenderer.burn(note: preparedNote.rendered, into: finalImage) else {
                presentError(title: "Failed to apply note", message: "Could not render the note text.")
                isFinalActionInProgress = false
                return
            }
            finalImage = noted
            burnedNoteText = preparedNote.identity
            // Carried editor edits become the new baseline; only the note round-trips.
            baselinePNG = baselinePNGForEmbedding(preNoteImage: pendingImage)
            embedPrompt = preparedNote.identity
            embedEditorState = pendingEditorState
        } else {
            burnedNoteText = ""
            embedEditorState = pendingEditorState
        }
        imageToPersist = finalImage
    } else {
        imageToPersist = nil
        if let note {
            guard applyNoteIfNeeded(note) else {
                isFinalActionInProgress = false
                return
            }
        }
    }

    guard persistImageIfNeeded(imageToPersist,
                               for: action,
                               baselinePNG: baselinePNG,
                               prompt: embedPrompt,
                               editorState: embedEditorState) else {
        isFinalActionInProgress = false
        return
    }
    guard performFinalActionEffects(action, copyAndDeleteImage: nil) else {
        isFinalActionInProgress = false
        return
    }
